def calculate_K(A_size, B_size, window):
    # A = {0, 1, ..., A_size - 1}
    # B = {0, 1, ..., B_size - 1}

    A = list(range(A_size))
    B = list(range(B_size))

    K = 0

    # Iterate over all m in A
    for m in A:
        count_n = 0
        # Iterate over all n in B
        for n in B:
            if abs(m - n) <= window:
                count_n += 1
        K += count_n

    return K

